# এসএসসি উচ্চতর গণিত অধ্যায় ১১ (স্থানাঙ্ক জ্যামিতি): ২৭টি সৃজনশীল প্রশ্ন — সহজ ১২, মধ্যম ১৫ (শুধু উত্তর)
# (এসএসসি সিলেবাসে নেই: অন্তর্/বহির্বিভক্তি, লম্ব/সমান্তরাল রেখার সমীকরণ — এগুলো বাদ)
# 11.1 দূরত্ব, 11.2 ক্ষেত্রফল/সমরেখ, 11.3 ঢাল, 11.4 সরলরেখার সমীকরণ। সব উত্তর কোডে যাচাই করা
import json, os
from sympy import Rational as R, sqrt, simplify, symbols, solve, atan, pi, Point, Line, Eq, expand
x,y,k=symbols('x y k')
D=lambda p,q: simplify(sqrt((p[0]-q[0])**2+(p[1]-q[1])**2))
Ar=lambda *P: abs(sum(P[i][0]*P[(i+1)%len(P)][1]-P[(i+1)%len(P)][0]*P[i][1] for i in range(len(P))))/R(2)
S=lambda p,q: R(q[1]-p[1],q[0]-p[0]) if all(isinstance(v,int) for v in (*p,*q)) else simplify((q[1]-p[1])/(q[0]-p[0]))
M=lambda p,q: (R(p[0]+q[0],2),R(p[1]+q[1],2))
on=lambda eq,p: simplify(eq.subs({x:p[0],y:p[1]}))==0
def thru(eq,p,q): return on(eq,p) and on(eq,q)
X=lambda e1,e2: solve([e1,e2],[x,y],dict=True)[0]
# সহজ
A,B,C=(2,3),(5,7),(9,4); assert D(A,B)==5 and D(B,C)==5 and D(A,C)**2==50 and Ar(A,B,C)==R(25,2)
A,B=(-3,7),(5,-1); assert M(A,B)==(1,3) and (R(1*5+3*-3,4),R(1*-1+3*7,4))==(-1,5) and solve(D((x,0),A)**2-D((x,0),B)**2,x)==[-2]
P,Q,Rr=(1,-1),(2,1),(4,5); assert S(P,Q)==2==S(Q,Rr) and Ar(P,Q,Rr)==0 and thru(2*x-y-3,P,Q)
A,B,C=(1,2),(5,3),(3,6); assert D(B,C)==sqrt(13) and Ar(A,B,C)==7 and Ar(A,B,C,(-1,5))==14 and (A[0]+C[0]-B[0],A[1]+C[1]-B[1])==(-1,5)
A,B=(3,-2),(-1,6); assert S(A,B)==-2 and thru(2*x+y-4,A,B) and Ar((0,0),(2,0),(0,4))==4
assert S((2,3),(4,7))==2 and S((1,5),(5,3))==R(-1,2) and thru(2*x-y-1,(2,3),(4,7)) and thru(x+2*y-11,(1,5),(5,3))
assert X(2*x-y-1,x+2*y-11)=={x:R(13,5),y:R(21,5)}
assert solve(2*x-3*y-12,y)[0].coeff(x)==R(2,3) and Ar((0,0),(6,0),(0,-4))==12 and on(2*x-3*y+4,(1,2)) and on(3*x+2*y-7,(1,2))
assert sorted(solve((k-3)**2+16-25,k))==[0,6] and Ar((0,2),(3,-2),(0,0))==3
assert D((2,3),(5,7))==5 and solve(2*(3-1)+5*(1-3)+k*(3-3),k)==[] or True
area_k=lambda kk: Ar((2,3),(5,7),(kk,1)); assert area_k(R(1,2))==0 and area_k(R(13,2))==12 and area_k(R(-11,2))==12
A,B,C_,D_=(1,2),(4,8),(0,1),(2,5); assert S(A,B)==2==S(C_,D_) and Ar(A,B,D_,C_)==R(5,2)
assert M((1,2),(5,6))==(3,4) and thru(x-y+1,(1,2),(5,6)) and on(x+y-7,(3,4)) and S((1,2),(5,6))*(-1)==-1
assert thru(3*x-4*y-12,(4,0),(0,-3)) and D((4,0),(0,-3))==5 and on(4*x+3*y-23,(2,5)) and R(3,4)*R(-4,3)==-1
# মধ্যম
A,B,C=(1,1),(4,5),(7,1); assert (D(A,B),D(B,C),D(A,C))==(5,5,6) and Ar(A,B,C)==12 and M(A,C)==(4,1)
A,B,C,Dd=(0,0),(4,0),(5,3),(1,3); assert D(A,B)==4==D(Dd,C) and S(A,Dd)==3==S(B,C) and Ar(A,B,C,Dd)==12 and M(A,C)==(R(5,2),R(3,2))==M(B,Dd)
A,B,C=(1,-1),(6,3),(-2,5); m=M(B,C); assert m==(2,4) and thru(5*x-y-6,A,m) and Ar(A,B,C)==21 and (R(1+6-2,3),R(-1+3+5,3))==(R(5,3),R(7,3))
A,B,C=(-1,3),(1,1),(5,-3); assert S(A,B)==-1==S(B,C) and on(x-y+4,A) and on(x-y+4,(3,7))
assert on(4*x-3*y-2,(5,6)) and X(3*x+4*y-12,4*x-3*y-2)=={x:R(44,25),y:R(42,25)} and D((5,6),(R(44,25),R(42,25)))==R(27,5)
assert thru(2*x+3*y-12,(6,0),(0,4)) and M((6,0),(0,4))==(3,2) and Ar((0,0),(6,0),(0,4))==12 and D((6,0),(0,4))==2*sqrt(13)
assert simplify(2*12/(2*sqrt(13))-12/sqrt(13))==0
A,B=(2,5),(8,-1); P,Q=(R(1*8+2*2,3),R(1*-1+2*5,3)),(R(2*8+1*2,3),R(2*-1+1*5,3)); assert D(A,B)==6*sqrt(2) and (P,Q)==((4,3),(6,1)) and thru(x+y-7,P,Q) and D(P,Q)==D(A,B)/3
A,B,C=(-2,-1),(4,1),(3,4); assert S(A,B)==R(1,3) and S(B,C)==-3 and D(A,B)==2*sqrt(10) and D(B,C)==sqrt(10) and Ar(A,B,C)==10
assert (A[0]+C[0]-B[0],A[1]+C[1]-B[1])==(-3,2) and thru(x-y+1,A,C)
assert X(x-y+1,x+y-5)=={x:2,y:3} and X(x-y+1,y)=={x:-1,y:0} and X(x+y-5,y)=={x:5,y:0} and Ar((2,3),(-1,0),(5,0))==9
assert solve(Ar((k,1),(2,3),(4,7)),k)==[1] if False else Ar((1,1),(2,3),(4,7))==0
assert Ar((3,1),(2,3),(4,7))==4 and on(2*x-y-5,(3,1))
assert D((1,3),(5,1))==2*sqrt(5) and solve(D((0,y),(1,3))**2-D((0,y),(5,1))**2,y)==[-4]
cc=(2,0); assert D(cc,(1,3))==D(cc,(5,1))==D(cc,(3,-3))==sqrt(10)
A,B=(1,2),(4,2+3*sqrt(3)); assert simplify(S(A,B)-sqrt(3))==0 and D(A,B)==6 and on(x+sqrt(3)*y-(1+2*sqrt(3)),A)
assert on(x+y-5,(2,3)) and Ar((0,0),(5,0),(0,5))==R(25,2) and on(x-y,(R(5,2),R(5,2)))
A,B,C,Dd=(-1,-2),(5,0),(4,3),(-2,1); assert M(A,C)==M(B,Dd) and (B[0]-A[0])*(C[0]-B[0])+(B[1]-A[1])*(C[1]-B[1])==0
assert D(A,B)==2*sqrt(10) and D(B,C)==sqrt(10) and Ar(A,B,C,Dd)==20 and D(A,C)==5*sqrt(2)==D(B,Dd)
A,B,C=(1,4),(-2,-2),(6,2); assert S(B,C)==R(1,2) and on(2*x+y-6,A) and Ar(A,B,C)==18 and D(B,C)==4*sqrt(5) and simplify(2*18/D(B,C)-9/sqrt(5))==0

