def clip(poly,f):
    # f(p) >= 0 অংশ রাখা (রৈখিক অর্ধতল); Sutherland–Hodgman
    out=[]; n_=len(poly)
    for i in range(n_):
        P_,Q_=poly[i],poly[(i+1)%n_]; fp,fq=f(P_),f(Q_)
        if fp>=0: out.append(P_)
        if (fp>=0)!=(fq>=0):
            t_=R(fp)/(fp-fq); out.append((P_[0]+t_*(Q_[0]-P_[0]),P_[1]+t_*(Q_[1]-P_[1])))
    return out
part=lambda poly,*fs: (lambda pp: Ar(*pp) if len(pp)>=3 else 0)(__import__('functools').reduce(clip,fs,poly))
BELOW=lambda p:-p[1]; ABOVE=lambda p:p[1]; RIGHT=lambda p:p[0]; LEFT=lambda p:-p[0]
